import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class LfuCacheDemo {

    private static final Logger log = Logger.getLogger(LfuCacheDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // FX rate cache (rate stored as paise per unit for integer simplicity), capacity 2.
        LfuCache cache = new LfuCache(2);

        cache.put("USD-INR", 8325L);          // freq 1
        cache.put("EUR-INR", 9010L);          // freq 1
        log.info(() -> "get USD-INR -> " + cache.get("USD-INR"));   // USD freq -> 2
        log.info(() -> "get USD-INR -> " + cache.get("USD-INR"));   // USD freq -> 3

        // New key, cache full: EUR-INR has lowest freq (1) -> evicted.
        cache.put("GBP-INR", 10550L);
        log.info(() -> "get EUR-INR -> " + cache.get("EUR-INR"));   // miss, evicted
        log.info(() -> "get USD-INR -> " + cache.get("USD-INR"));   // hit
        log.info(() -> "get GBP-INR -> " + cache.get("GBP-INR"));   // hit
    }
}

