class LfuCache {

    private static final Logger log = Logger.getLogger(LfuCache.class.getName());

    private final int capacity;
    private int minFrequency;
    private final Map<String, Entry> values = new HashMap<>();
    private final Map<Integer, LinkedHashSet<String>> buckets = new HashMap<>();

    LfuCache(int capacity) {
        this.capacity = capacity;
        this.minFrequency = 0;
    }

    // O(1): read value and promote frequency.
    Long get(String key) {
        Entry entry = values.get(key);
        if (entry == null) {
            log.fine(() -> "MISS " + key);
            return null;
        }
        promote(key, entry);
        log.fine(() -> "HIT " + key + " freq now " + entry.frequency);
        return entry.value;
    }

    // O(1): insert or update, evict LFU (then LRU tie-break) if over capacity.
    void put(String key, long value) {
        if (capacity <= 0) return;
        Entry existing = values.get(key);
        if (existing != null) {
            existing.value = value;
            promote(key, existing);
            return;
        }
        if (values.size() >= capacity) {
            LinkedHashSet<String> minBucket = buckets.get(minFrequency);
            String evictKey = minBucket.iterator().next();   // oldest among least frequent
            minBucket.remove(evictKey);
            values.remove(evictKey);
            log.info(() -> "EVICT " + evictKey + " (freq " + minFrequency + ")");
        }
        values.put(key, new Entry(value));
        buckets.computeIfAbsent(1, k -> new LinkedHashSet<>()).add(key);
        minFrequency = 1;                                     // new key always freq 1
    }

    private void promote(String key, Entry entry) {
        int oldFreq = entry.frequency;
        LinkedHashSet<String> oldBucket = buckets.get(oldFreq);
        oldBucket.remove(key);
        if (oldFreq == minFrequency && oldBucket.isEmpty()) {
            minFrequency++;                                   // no key at old min anymore
        }
        entry.frequency = oldFreq + 1;
        buckets.computeIfAbsent(entry.frequency, k -> new LinkedHashSet<>()).add(key);
    }
}

